function closeModelMenu(focus){const menu=document.getElementById('model-menu');if(!menu)return;menu.remove();const b=document.getElementById('home');b.setAttribute('aria-expanded','false');if(focus)b.focus()}
// Header quick switch: one model answers each message; the menu changes which one without opening Settings.
function toggleModelMenu(){if(document.getElementById('model-menu')){closeModelMenu(false);return}const es=lang==='es';const b=document.getElementById('home');const menu=document.createElement('div');menu.id='model-menu';menu.setAttribute('role','group');menu.setAttribute('aria-label',es?'Elegir modelo':'Choose model');models.forEach(m=>{const item=document.createElement('button');item.type='button';item.className='model-menu-item';item.setAttribute('aria-pressed',String(m.id===preferredModel));const n=document.createElement('span');n.textContent=m.name;const st=typeof aiStatus==='function'?aiStatus(m.id):null;if(st){const small=document.createElement('small');small.className='model-status '+st.kind;small.textContent=st.text;n.append(small)}item.append(n);item.onclick=()=>{preferredModel=m.id;saveModels();updateModelLabel();closeModelMenu(true)};menu.append(item)});const manage=document.createElement('button');manage.type='button';manage.className='model-menu-manage';manage.textContent=es?'Administrar modelos':'Manage models';manage.onclick=()=>{closeModelMenu(false);settingsTab='models';showSettings();settingsDialog.showModal()};menu.append(manage);menu.addEventListener('focusout',()=>setTimeout(()=>{const a=document.activeElement;if(document.getElementById('model-menu')===menu&&a&&a!==document.body&&!menu.contains(a)&&a.id!=='home')closeModelMenu(false)},0));b.after(menu);b.setAttribute('aria-expanded','true');(menu.querySelector('[aria-pressed="true"]')||menu.querySelector('button')).focus()}
document.addEventListener('click',e=>{const menu=document.getElementById('model-menu');if(menu&&!menu.contains(e.target)&&!e.target.closest?.('#home'))closeModelMenu(false)});document.addEventListener('keydown',e=>{const menu=document.getElementById('model-menu');if(e.key==='Escape'&&menu){const a=document.activeElement;closeModelMenu(menu.contains(a)||a?.id==='home')}});
const modelObserver=new MutationObserver(()=>{const expected=(models.find(m=>m.id===preferredModel)||models[0]).name+' ⌄';if(document.getElementById('home').textContent!==expected)updateModelLabel()});modelObserver.observe(document.getElementById('home'),{childList:true});updateModelLabel();

function closeAccountMenu(){document.getElementById('account-menu').hidden=true;document.getElementById('account-toggle').setAttribute('aria-expanded','false')}
const accountToggle=document.getElementById('account-toggle');accountToggle.onclick=()=>{const menu=document.getElementById('account-menu');menu.hidden=!menu.hidden;accountToggle.setAttribute('aria-expanded',String(!menu.hidden));document.getElementById('settings-open').textContent=lang==='es'?'⚙ Configuración':'⚙ Settings';if(!menu.hidden)document.getElementById('settings-open').focus()};document.addEventListener('click',e=>{if(!e.target.closest('#account-toggle')&&!e.target.closest('#account-menu'))closeAccountMenu()});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!document.getElementById('account-menu').hidden){closeAccountMenu();accountToggle.focus()}});

let themeMode='system',fontSize='normal';try{themeMode=localStorage.getItem('nuna-theme-mode')||(localStorage.getItem('nuna-theme')?'manual':'dark');if(themeMode==='manual')themeMode=dark?'dark':'light';fontSize=localStorage.getItem('nuna-font-size')||'normal'}catch{}const systemAppearance=matchMedia('(prefers-color-scheme: dark)');function applySystemPreferences(){dark=themeMode==='system'?systemAppearance.matches:themeMode==='dark';save();render();updateProfile();document.body.dataset.fontSize=fontSize}systemAppearance.addEventListener('change',()=>{if(themeMode==='system')applySystemPreferences()});const quickTheme=document.getElementById('theme');quickTheme.onclick=()=>{themeMode=dark?'light':'dark';try{localStorage.setItem('nuna-theme-mode',themeMode)}catch{}applySystemPreferences()};applySystemPreferences();
